'use strict';

function debounce(fn, ms, timers) {
  let id = null;
  let lastArgs;
  const debounced = (...args) => {
    lastArgs = args;
    if (id !== null) timers.clearTimeout(id);
    id = timers.setTimeout(() => {
      id = null;
      fn(...lastArgs);
    }, ms);
  };
  debounced.cancel = () => {
    if (id !== null) {
      timers.clearTimeout(id);
      id = null;
    }
  };
  debounced.flush = () => {
    if (id !== null) {
      timers.clearTimeout(id);
      id = null;
      fn(...lastArgs);
    }
  };
  return debounced;
}

