'use strict';

function debounce(fn, ms, timers) {
  let id = null;
  let lastArgs;
  const debounced = (...args) => {
    lastArgs = args;
    if (id !== null) timers.clearTimeout(id);
    id = timers.setTimeout(() => {
      id = null;
      fn(...lastArgs);
    }, ms);
  };
  debounced.cancel = () => {
    if (id !== null) {
      timers.clearTimeout(id);
      id = null;
    }
  };
  debounced.flush = () => {
    if (id !== null) {
      timers.clearTimeout(id);
      id = null;
      fn(...lastArgs);
    }
  };
  return debounced;
}

function throttle(fn, ms, timers) {
  let lastRun = -Infinity;
  let id = null;
  let pending;
  const run = (args) => {
    fn(...args);
  };
  const throttled = (...args) => {
    const remaining = lastRun + ms - timers.now();
    lastRun = timers.now();
    if (remaining <= 0) {
      if (id !== null) {
        timers.clearTimeout(id);
        id = null;
      }
      run(args);
    } else {
      pending = args;
      if (id === null) {
        id = timers.setTimeout(() => {
          id = null;
          run(pending);
        }, remaining);
      }
    }
  };
  throttled.cancel = () => {
    if (id !== null) {
      timers.clearTimeout(id);
      id = null;
    }
  };
  return throttled;
}

module.exports = { debounce, throttle };

